const req = $input.first().json;
let body = req.body || req;
// beacons arrive as text/plain (no CORS preflight, survives document.write), so the body is a raw string
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const headers = req.headers || {};

// Salted fingerprint of the source network. Deliberately NOT the raw IP:
// gives a stable "same network as before / new network" signal without being a location readout.
const SALT = 'sa-2026-08-03-b7f31c9d4e';
function fingerprint(ip) {
  if (!ip) return 'unknown';
  const s = SALT + '|' + ip;
  let h1 = 0x811c9dc5, h2 = 0x9e3779b1;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x85ebca6b) >>> 0;
  }
  return (h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0')).slice(0, 10);
}

const xff = headers['x-forwarded-for'] || headers['cf-connecting-ip'] || '';
const ip = String(xff).split(',')[0].trim();
const ua = String(headers['user-agent'] || '');

function device(u) {
  if (/iPad/i.test(u)) return 'iPad';
  if (/iPhone/i.test(u)) return 'iPhone';
  if (/Android/i.test(u)) return 'Android';
  if (/Macintosh|Mac OS X/i.test(u)) return 'Mac';
  if (/Windows/i.test(u)) return 'Windows';
  return 'Unknown';
}
function browser(u) {
  if (/CriOS/i.test(u)) return 'Chrome (iOS)';
  if (/FxiOS/i.test(u)) return 'Firefox (iOS)';
  if (/Edg\//i.test(u)) return 'Edge';
  if (/Chrome\//i.test(u)) return 'Chrome';
  if (/Firefox\//i.test(u)) return 'Firefox';
  if (/Safari/i.test(u)) return 'Safari';
  return 'Other';
}
const isBot = /bot|crawl|spider|slurp|preview|monitor|curl|wget|python-requests|headless|lighthouse|pingdom|uptime/i.test(ua);

const events = Array.isArray(body.events) ? body.events : [body];
const out = [];
for (const e of events) {
  out.push({ json: {
    timestamp: e.ts || new Date().toISOString(),
    app: body.app || e.app || 'unknown',
    event: e.event || '',
    sessionId: e.sid || '',
    networkId: fingerprint(ip),
    device: device(ua),
    browser: browser(ua),
    detail: JSON.stringify(e.data || {}).slice(0, 2000),
    isBot: isBot
  }});
}
return out;

// Only these are worth waking Jordan up for. A bare page load (gate_open) is logged but never alerted:
// the URLs are public, so crawlers hit them constantly. Typing a password is the real signal.
const ALERT_ON = { unlock_ok: 1, unlock_fail: 1, auto_unlock: 1, session_end: 1 };

const APP = {
  study: 'Study app (physical therapy quiz)',
  ytcourse: 'YouTube course',
  ytquiz: '14-day quiz app'
};
const HEAD = {
  unlock_ok:   ['🔓', 'Correct password entered — they are in'],
  auto_unlock: ['🔓', 'Opened it (remembered password, nothing typed)'],
  unlock_fail: ['⛔', 'WRONG password entered'],
  session_end: ['⏹️', 'Session finished']
};

function dur(ms) {
  if (!ms || ms < 0) return null;
  const s = Math.round(ms / 1000);
  if (s < 60) return s + 's';
  const m = Math.floor(s / 60);
  return m + 'm ' + (s % 60) + 's';
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!ALERT_ON[j.event] || j.isBot) continue;

  const app = APP[j.app] || j.app;
  const h = HEAD[j.event] || ['🔔', j.event];
  const when = new Date(j.timestamp).toLocaleString('en-GB', {
    timeZone: 'Asia/Bangkok', weekday: 'short', day: 'numeric', month: 'short',
    hour: '2-digit', minute: '2-digit', hour12: false
  });

  let d = {};
  try { d = JSON.parse(j.detail || '{}'); } catch (e) {}

  const lines = [];
  lines.push('*App:* ' + app);
  lines.push('*Time:* ' + when + '  (Bangkok)');
  lines.push('*Network:* `' + j.networkId + '`');
  lines.push('*Device:* ' + j.device + ' · ' + j.browser);

  const spent = dur(d.ms);
  if (spent) lines.push('*Open for:* ' + spent);
  if (d.actions) lines.push('*What they did:* ' + String(d.actions).slice(0, 800));
  if (j.event === 'unlock_fail') {
    lines.push('*Attempt:* ' + (d.len ? d.len + ' characters typed' : 'password rejected'));
  }
  lines.push('*Session:* `' + (j.sessionId || 'n/a') + '`');

  const subject = h[0] + ' ' + app + ' — ' + h[1];
  const slackText = '*' + h[0] + ' ' + h[1] + '*\n' + lines.join('\n');

  const rows = lines.map(l => {
    const m = l.match(/^\*([^*]+):\*\s*(.*)$/);
    const k = m ? m[1] : '';
    const v = m ? m[2].replace(/`/g, '') : l;
    return '<tr><td style="padding:6px 12px;color:#888;white-space:nowrap">' + k +
           '</td><td style="padding:6px 12px;color:#fff;font-weight:600">' + v + '</td></tr>';
  }).join('');

  const body = '<div style="font-family:system-ui,sans-serif;max-width:560px;margin:0 auto;' +
    'background:#0f0f1a;color:#e0e0e0;border-radius:12px;overflow:hidden">' +
    '<div style="background:' + (j.event === 'unlock_fail' ? '#b91c1c' : '#7c3aed') +
    ';padding:18px 22px"><h2 style="margin:0;color:#fff;font-size:18px">' + h[0] + ' ' + h[1] +
    '</h2></div><div style="padding:18px 10px"><table style="width:100%;border-collapse:collapse">' +
    rows + '</table><p style="text-align:center;color:#666;font-size:11px;margin-top:18px">' +
    '<a href="https://docs.google.com/spreadsheets/d/' + '1hiq8_GgMdl9-t83GsqZqDsUulCSajPdf3EDp5SKiGrM' + '" ' +
    'style="color:#3b82f6">Full access log</a></p></div></div>';

  out.push({ json: { subject: subject, slackText: slackText, body: body } });
}
return out;
